function HistoryDetailPage({slug}:{slug:string}){
  if(slug==='brasil-antigo')return <KnowledgeDetailPage kind="prehistory" slug="brasil-antigo"/>;
  if(slug==='canones-biblicos'){
    const guide=CONTENT_V45_BY_ID.get('pt-leitura');
    const guidePath='/content/historia/contexto_historico_canones_biblicos.md';
    return <HistoryGuidePage title="Formação dos cânones bíblicos" path={guidePath} image="/assets/knowledge/knowledge-radar.svg" fallbackLink="/historia" />;
  }
  return <HistoryPage/>;
}
function HistoryGuidePage({title,path:guidePath,image,fallbackLink}:{title:string;path:string;image:string;fallbackLink:string}){
  const [text,setText]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');
  useEffect(()=>{let alive=true;fetchLocalText(guidePath).then(v=>alive&&setText(v)).catch(e=>alive&&setError(String(e))).finally(()=>alive&&setLoading(false));return()=>{alive=false}},[guidePath]);
  const blocks=text.replace(/\r/g,'').split('\n').filter(Boolean).map((line,i)=>{const t=line.trim();if(t.startsWith('# '))return <h2 key={i}>{t.slice(2)}</h2>;if(t.startsWith('## '))return <h3 key={i}>{t.slice(3)}</h3>;if(t.startsWith('### '))return <h4 key={i}>{t.slice(4)}</h4>;if(t.startsWith('- '))return <p key={i}>• {t.slice(2)}</p>;return <p key={i}>{formatInlineGuideText(t)}</p>});
  return <div className="stack-lg"><Link className="back-link" href={fallbackLink}><ArrowLeft size={15}/> História</Link><section className="content-guide-hero"><img src={image} alt=""/><div><div className="eyebrow accent-text">História · guia</div><h1>{title}</h1><p>Fonte editorial organizada para leitura interna, com referências e limites de interpretação.</p></div></section><article className="surface guide-reading">{loading?<div className="skeleton-lines"><i/><i/><i/><i/></div>:error?<div className="empty-state"><WifiOff size={26}/><b>Não foi possível carregar o conteúdo.</b><span>{error}</span><Link className="secondary-btn" href={fallbackLink}>Voltar</Link></div>:blocks}</article></div>
}
